import { mkdir, writeFile } from 'node:fs/promises';
import { dirname, join } from 'node:path';
import type { AppModel, ScrapedForm, ScrapedPage } from './model';

/**
 * PowerBase scaffold generator — turns a recon AppModel into reviewable
 * starting points for test creation: page objects and smoke specs.
 *
 * This is deliberately a *scaffold* generator, not a suite generator (see
 * docs/adr-003-recon-scaffolds.md). Generated files are clearly stamped,
 * placed under generated/ directories, and never overwrite human code
 * unless forced. The engineer reviews, renames, and promotes what is
 * worth keeping — the framework never silently rewrites the suite.
 */

export interface GeneratedFile {
	/** Path relative to the project root, e.g. src/pages/generated/login.page.ts */
	path: string;
	content: string;
}

export interface GenerateOptions {
	/** Overwrite files that already exist. Default false. */
	force?: boolean;
	/** Fail smoke specs on console errors (recorded count becomes the budget). Default true. */
	strictConsoleErrors?: boolean;
}

function slugFor(path: string): string {
	const slug = path
		.split('?')[0]
		?.replace(/[^a-zA-Z0-9]+/g, '-')
		.replace(/^-+|-+$/g, '')
		.toLowerCase();
	return slug === '' ? 'home' : (slug ?? 'home');
}

function classFor(slug: string): string {
	return `${slug
		.split('-')
		.map((p) => p.charAt(0).toUpperCase() + p.slice(1))
		.join('')}Page`;
}

function header(command: string): string {
	return `/**\n * GENERATED by PowerBase recon — review before use.\n *\n * This is a scaffold, not a finished test asset. Inspect it, rename it,\n * move it out of generated/, and delete what the app doesn't need.\n * Regenerate with: ${command}\n */\n\n`;
}

/** Best-effort Playwright locator expression for a scraped field. */
export function locatorForField(field: {
	name: string;
	type: string;
	label: string;
}): string {
	if (field.label)
		return `this.page.getByLabel(${JSON.stringify(field.label)})`;
	if (field.name)
		return `this.page.locator(${JSON.stringify(`[name="${field.name}"]`)})`;
	return `this.page.getByRole(${JSON.stringify(field.type === 'checkbox' ? 'checkbox' : 'textbox')})`;
}

/** Sanitize free text into a valid TS identifier fragment. */
export function identifierFor(text: string, fallback: string): string {
	const clean = text
		.toLowerCase()
		.replace(/[^a-z0-9]+/g, ' ')
		.trim()
		.split(' ')
		.map((w, i) => (i === 0 ? w : w.charAt(0).toUpperCase() + w.slice(1)))
		.join('');
	if (!clean) return fallback;
	// Identifiers can't start with a digit.
	return /^[0-9]/.test(clean) ? `_${clean}` : clean;
}

function pageObjectFor(pageModel: ScrapedPage, command: string): GeneratedFile {
	const slug = slugFor(pageModel.path);
	const className = classFor(slug);
	const urlGlob = `**${pageModel.path.split('?')[0]}**`;
	const lines: string[] = [
		`export class ${className} {`,
		`\treadonly path = ${JSON.stringify(pageModel.path)};`,
		'',
		"\tconstructor(private readonly page: import('@playwright/test').Page) {}",
		'',
		'\tasync goto(): Promise<void> {',
		'\t\tawait this.page.goto(this.path);',
		'\t}',
		'',
		'\tasync expectLoaded(): Promise<void> {',
		`\t\tawait this.page.waitForURL(${JSON.stringify(urlGlob)});`,
		'\t}',
	];

	const usedProps = new Set<string>();
	for (const form of pageModel.forms) {
		lines.push(
			'',
			`\t// Form: ${form.identifier} (${form.method.toUpperCase()} ${form.action || '(same page)'}, purpose: ${form.purpose})`,
		);
		for (const field of form.fields) {
			let prop = identifierFor(field.label || field.name, `${field.type}Field`);
			for (let i = 2; usedProps.has(prop); i++) {
				prop = `${identifierFor(field.label || field.name, `${field.type}Field`)}${i}`;
			}
			usedProps.add(prop);
			lines.push(
				`\tget ${prop}(): import('@playwright/test').Locator {`,
				`\t\treturn ${locatorForField(field)};`,
				'\t}',
			);
		}
		// Prefer the scraped submit-button text; fall back to a purpose
		// guess only when the crawler found no button.
		const submitText = form.submitText || submitNameFor(form);
		if (submitText) {
			let prop = identifierFor(submitText, 'submit');
			if (!/button$/i.test(prop)) prop += 'Button';
			for (let i = 2; usedProps.has(prop); i++) {
				prop = `${identifierFor(submitText, 'submit')}Button${i}`;
			}
			usedProps.add(prop);
			lines.push(
				`\tget ${prop}(): import('@playwright/test').Locator {`,
				`\t\treturn this.page.getByRole('button', { name: ${JSON.stringify(submitText)} });`,
				'\t}',
			);
		}
	}

	lines.push('}', '');
	return {
		path: `src/pages/generated/${slug}.page.ts`,
		content: `${header(command)}${lines.join('\n')}`,
	};
}

/** Heuristic submit-button name from the form's purpose. */
function submitNameFor(form: ScrapedForm): string | null {
	switch (form.purpose) {
		case 'login':
			return 'Sign in';
		case 'search':
			return 'Search';
		case 'register':
			return 'Sign up';
		default:
			return null;
	}
}

function smokeSpecFor(
	pageModel: ScrapedPage,
	command: string,
	options: GenerateOptions,
): GeneratedFile {
	const slug = slugFor(pageModel.path);
	const className = classFor(slug);
	const strictErrors = options.strictConsoleErrors !== false;
	const lines: string[] = [
		`import { expect, test } from '@playwright/test';`,
		`import { ${className} } from '../../../src/pages/generated/${slug}.page';`,
		'',
		`test.describe('${slug} smoke (generated)', () => {`,
		`\ttest('loads with status ${pageModel.status}', async ({ page }) => {`,
		'\t\tconst errors: string[] = [];',
		"\t\tpage.on('console', (msg) => {",
		"\t\t\tif (msg.type() === 'error') errors.push(msg.text());",
		'\t\t});',
		`\t\tconst target = new ${className}(page);`,
		`\t\tconst response = await page.goto(target.path);`,
		`\t\texpect(response?.status(), 'HTTP status').toBe(${pageModel.status});`,
		'\t\tawait target.expectLoaded();',
	];
	if (pageModel.title) {
		lines.push(
			`\t\tawait expect(page).toHaveTitle(${JSON.stringify(pageModel.title)});`,
		);
	}
	if (strictErrors) {
		lines.push(
			// biome-ignore lint/suspicious/noTemplateCurlyInString: ${...} is intentional, belongs to the GENERATED spec.
			'\t\texpect(errors, `console errors on ${target.path}`).toEqual([]);',
		);
	}
	for (const form of pageModel.forms) {
		lines.push(
			`\t\t// Form "${form.identifier}" (${form.method.toUpperCase()} ${form.action || '(same page)'}) present on load.`,
			`\t\tawait expect(page.locator('form')).not.toHaveCount(0);`,
		);
	}
	lines.push('\t});', '});', '');
	return {
		path: `tests/e2e/generated/${slug}.smoke.spec.ts`,
		content: `${header(command)}${lines.join('\n')}`,
	};
}

/**
 * Generate page objects + smoke specs from a model. Pure: returns files,
 * writes nothing. Use writeGenerated() to persist.
 */
export function generateFromModel(
	model: AppModel,
	command: string,
	options: GenerateOptions = {},
): GeneratedFile[] {
	const files: GeneratedFile[] = [];
	for (const pageModel of model.pages) {
		// Only scaffold real pages, not API routes or error pages.
		if (pageModel.status !== 200) continue;
		if (pageModel.path.startsWith('/api/')) continue;
		files.push(pageObjectFor(pageModel, command));
		files.push(smokeSpecFor(pageModel, command, options));
	}
	return files;
}

/** Write generated files to disk. Skips existing files unless force. */
export async function writeGenerated(
	files: GeneratedFile[],
	projectRoot: string,
	options: GenerateOptions = {},
): Promise<{ written: string[]; skipped: string[] }> {
	const written: string[] = [];
	const skipped: string[] = [];
	const { existsSync } = await import('node:fs');
	for (const file of files) {
		const abs = join(projectRoot, file.path);
		if (existsSync(abs) && !options.force) {
			skipped.push(file.path);
			continue;
		}
		await mkdir(dirname(abs), { recursive: true });
		await writeFile(abs, file.content, 'utf8');
		written.push(file.path);
	}
	return { written, skipped };
}
